-- Seed data: fictional accounts with posts, reels, stories and notes.
-- Generated by tool/seed/generate_seed.py. Run it in the Supabase SQL
-- editor AFTER supabase/schema.sql (all updates). Safe to run again: it
-- refreshes the stories and notes so they don't expire.
-- Seed accounts use @seed.invalid emails and no password: nobody can log
-- in as them. supabase/seed_remove.sql deletes all of them.

begin;

-- Verified badge, category and a seed marker on profiles.
alter table public.profiles add column if not exists is_verified boolean not null default false;
alter table public.profiles add column if not exists category text;
alter table public.profiles add column if not exists is_seed boolean not null default false;

